#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998244353LL;
    long long value;

    Mod998() : value(0) {}
    Mod998(long long v) : value((v % MOD + MOD) % MOD) {}

    static long long mod() { return MOD; }

    static long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    static long long subtract(long long a, long long b) {
        return (a - b + MOD) % MOD;
    }

    static long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    static long long inv(long long a) {
        // Fermat's little theorem for prime modulus
        return pow_mod(a, MOD - 2);
    }

    static long long pow_mod(long long base, long long exp) {
        long long result = 1;
        long long b = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = (result * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return result;
    }
};

struct NumberTheory {
    struct Mod998 {
        static long long modulus() { return 998244353LL; }
        long long value;

        Mod998() : value(0) {}
        Mod998(long long v) : value((v % modulus() + modulus()) % modulus()) {}

        static long long add(long long a, long long b) {
            return (a + b) % modulus();
        }

        static long long subtract(long long a, long long b) {
            return (a - b + modulus()) % modulus();
        }

        static long long mult(long long a, long long b) {
            return (a * b) % modulus();
        }

        static long long inv(long long a) {
            return pow_mod(a, modulus() - 2);
        }

        static long long pow_mod(long long base, long long exp) {
            long long result = 1;
            long long b = base % modulus();
            while (exp > 0) {
                if (exp & 1) result = (result * b) % modulus();
                b = (b * b) % modulus();
                exp >>= 1;
            }
            return result;
        }
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    // Precompute factorials and inverse factorials for nCr
    int maxN = n;
    vector<long long> fact(n + 1, 1);
    vector<long long> invFact(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % Mod998::MOD;
    }
    invFact[n] = Mod998::inv(fact[n]);
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = (invFact[i + 1] * (i + 1)) % Mod998::MOD;
    }

    auto nCr = [&](int a, int b) -> long long {
        if (b < 0 || b > a) return 0;
        return (((fact[a] * invFact[b]) % Mod998::MOD) * invFact[a - b]) % Mod998::MOD;
    };

    // Compute modular inverse of (n + m)
    long long invNPlusM = Mod998::inv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; ; i++) {
        long long denom = (n + m - i);
        if (denom == 0) break;
        long long invDenom = Mod998::inv(denom);
        p = (p * (n - i)) % Mod998::MOD;
        p = (p * invDenom) % Mod998::MOD;
        phaseSize = (phaseSize + p) % Mod998::MOD;
        if (p == 0) break;
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = ((m + k) * Mod998::inv(k)) % Mod998::MOD;
        long long term = (nCr(n, k) * numPhases) % Mod998::MOD;
        term = (term * phaseSize) % Mod998::MOD;
        if (k & 1) {
            answer = (answer + term) % Mod998::MOD;
        } else {
            answer = (answer - term + Mod998::MOD) % Mod998::MOD;
        }
    }

    cout << answer << "\n";

    return 0;
}
